class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        count = defaultdict(int)
        n = len(s)

        for i in range(n):
            for j in range(i, n):
                sub = s[i:j+1]
                if len(set(sub)) == 1:
                    count[sub] += 1

        result = -1
        for sub, cnt in count.items():
            if cnt >= 3:
                result = max(result, len(sub))

        return result
